    letter-spacing: 0.08em;
    background: #e0efff;
    color: #2c6fad;
    padding: 0.2rem 0.6rem;
    border-radius: 0.3rem;
    margin-bottom: 1rem;
  }

  .content p {
    margin-bottom: 1rem;
    font-size: 0.95rem;
  }

  .content p:last-child {
    margin-bottom: 0;
  }

  .content ol {
    margin: 0.75rem 0 1rem 1.5rem;
