<html lang="ar" dir="rtl">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>الطبقات الجيولوجية للأرض | Earth's Geological Layers</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }

  body {
    font-family: "Segoe UI", Tahoma, Arial, sans-serif;
    background: linear-gradient(180deg, #0f0c29, #302b63, #24243e);
    min-height: 100vh;
    color: #f0f0f0;
    line-height: 1.8;
  }

  header {
    text-align: center;
    padding: 3rem 2rem 2rem;
  }

  header h1 {
    font-size: 2.4rem;
    font-weight: 800;
    background: linear-gradient(90deg, #f6d365, #fda085);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    margin-bottom: 0.5rem;
  }

  header p {
    font-size: 1.1rem;
    color: #a0a0c0;
  }

  .container {
    max-width: 1100px;
    margin: 0 auto;
    padding: 0 1.5rem 4rem;
  }

  /* Earth Diagram */
  .diagram-section {
    display: flex;
    justify-content: center;
    margin: 2rem 0 3rem;
  }

  .earth-svg-container {
    position: relative;
  }

  .earth-svg-container svg {
    filter: drop-shadow(0 0 40px rgba(255, 160, 60, 0.3));
  }

  /* Layer Cards */
  .layers-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 1.5rem;
    margin-top: 2rem;
  }

  .layer-card {
    background: rgba(255,255,255,0.05);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 1rem;
    padding: 1.8rem;
    backdrop-filter: blur(10px);
    transition: transform 0.3s ease, box-shadow 0.3s ease;
    position: relative;
    overflow: hidden;
  }

  .layer-card::before {
    content: '';
    position: absolute;
    top: 0;
    right: 0;
    left: 0;
    height: 4px;
    border-radius: 1rem 1rem 0 0;
  }

  .layer-card.crust::before { background: linear-gradient(90deg, #8B7355, #A0926B); }
  .layer-card.mantle::before { background: linear-gradient(90deg, #e85d04, #dc2f02); }
  .layer-card.core::before { background: linear-gradient(90deg, #ffd700, #ff8c00); }

  .layer-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 12px 40px rgba(0,0,0,0.3);
  }

  .layer-card h3 {
    font-size: 1.3rem;
    margin-bottom: 0.8rem;
    display: flex;
    align-items: center;
    gap: 0.5rem;
  }

  .layer-card.crust h3 { color: #C4A882; }
  .layer-card.mantle h3 { color: #ff6b35; }
  .layer-card.core h3 { color: #ffd700; }

  .layer-card .emoji {
    font-size: 1.5rem;
  }

  .layer-card p {
    font-size: 0.92rem;
    color: #c0c0d8;
    margin-bottom: 1rem;
  }

  .stats {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0.6rem;
    margin-top: 1rem;
  }

  .stat {
    background: rgba(255,255,255,0.04);
    border-radius: 0.5rem;
    padding: 0.7rem;
    text-align: center;
  }

  .stat .label {
    font-size: 0.72rem;
    color: #8888aa;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    margin-bottom: 0.2rem;
  }

  .stat .value {
    font-size: 1rem;
    font-weight: 700;
    color: #e0e0f0;
  }

  /* Fun Facts */
  .facts {
    margin-top: 3rem;
    background: rgba(255,255,255,0.03);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 1rem;
    padding: 1.8rem;
  }

  .facts h2 {
    font-size: 1.2rem;
    margin-bottom: 1rem;
    color: #f0d060;
  }

  .facts ul {
    list-style: none;
    padding: 0;
  }

  .facts ul li {
    padding: 0.5rem 0;
    border-bottom: 1px solid rgba(255,255,255,0.05);
    font-size: 0.92rem;
    color: #b0b0cc;
  }

  .facts ul li:last-child {
    border-bottom: none;
  }

  .facts ul li::before {
    content: '🌍 ';
    margin-left: 0.5rem;
  }

  footer {
    text-align: center;
    padding: 2rem;
    color: #555570;
    font-size: 0.85rem;
    border-top: 1px solid rgba(255,255,255,0.05);
  }

  /* Labels on SVG */
  .svg-label {
    font-family: "Segoe UI", Tahoma, Arial, sans-serif;
    font-size: 13px;
    fill: #fff;
    font-weight: 600;
  }

  .svg-label-sub {
    font-family: "Segoe UI", Tahoma, Arial, sans-serif;
    font-size: 10px;
    fill: rgba(255,255,255,0.7);
  }

  @media (max-width: 700px) {
    header h1 { font-size: 1.6rem; }
    .layers-grid { grid-template-columns: 1fr; }
    .diagram-section svg { width: 280px; height: 280px; }
  }
</style>
</head>
<body>

<header>
  <h1>الطبقات الجيولوجية للأرض</h1>
  <p>رحلة إلى أعماق كوكبنا</p>
</header>

<div class="container">

  <!-- Earth Cross-Section Diagram -->
  <div class="diagram-section">
    <div class="earth-svg-container">
      <svg width="360" height="360" viewBox="0 0 360 360">
        <defs>
          <radialGradient id="coreGrad" cx="50%" cy="50%" r="50%">
            <stop offset="0%" style="stop-color:#fff7e0"/>
            <stop offset="60%" style="stop-color:#ffd700"/>
            <stop offset="100%" style="stop-color:#ff8c00"/>
          </radialGradient>
          <radialGradient id="outerCoreGrad" cx="50%" cy="50%" r="50%">
            <stop offset="0%" style="stop-color:#ff8c00"/>
            <stop offset="100%" style="stop-color:#dc2f02"/>
          </radialGradient>
          <radialGradient id="mantleGrad" cx="50%" cy="50%" r="50%">
            <stop offset="0%" style="stop-color:#dc2f02"/>
            <stop offset="100%" style="stop-color:#9d0208"/>
          </radialGradient>
          <radialGradient id="crustGrad" cx="50%" cy="50%" r="50%">
            <stop offset="0%" style="stop-color:#2d6a4f"/>
            <stop offset="40%" style="stop-color:#40916c"/>
            <stop offset="70%" style="stop-color:#74a088"/>
            <stop offset="100%" style="stop-color:#8B7355"/>
          </radialGradient>
          <filter id="glow">
            <feGaussianBlur stdDeviation="3" result="coloredBlur"/>
            <feMerge>
              <feMergeNode in="coloredBlur"/>
              <feMergeNode in="SourceGraphic"/>
            </feMerge>
          </filter>
        </defs>

        <!-- Outer glow -->
        <circle cx="180" cy="180" r="170" fill="none" stroke="rgba(100,150,255,0.1)" stroke-width="8"/>

        <!-- Crust (outermost) -->
        <circle cx="180" cy="180" r="165" fill="url(#crustGrad)"/>

